"""消融实验（baseline vs no_replan）指标聚合。"""

CSR_KEYS = ("categoryScore", "priceScore", "scoreScore", "distanceScore")


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def compute_deltas(baseline, variant):
    """计算变体相对 baseline 的指标差异。"""
    deltas = {}
    for key, base_value in baseline.items():
        if key not in variant:
            continue
        variant_value = variant[key]
        if not (_is_number(base_value) and _is_number(variant_value)):
            continue
        deltas[key] = {
            "baseline": base_value,
            "variant": variant_value,
            "delta": round(variant_value - base_value, 4),
            "deltaPct": round((variant_value - base_value) / base_value * 100, 2) if base_value != 0 else 0.0,
        }
    return deltas


def _csr(row):
    """约束满足率：category/price/score/distance 四项分的综合值。"""
    scores = []
    for key in CSR_KEYS:
        value = row.get(key, 1.0)
        if not _is_number(value):
            value = 1.0
        scores.append(min(float(value), 1.0))
    return round(sum(scores) / len(scores), 4)


def _tokens(row):
    usage = row.get("tokenUsage") or {}
    value = usage.get("totalTokens", 0)
    return value if _is_number(value) else 0


def _side(row, csr):
    return {
        "iterations": row.get("iterations", 0),
        "candidateCount": row.get("candidateCount", 0),
        "reflectionScore": row.get("reflectionScore", 0),
        "csr": csr,
        "totalTokens": _tokens(row),
        "responseTimeMs": row.get("responseTimeMs", 0.0),
    }


def compare_replan(baseline_results, noreplan_results):
    """在 baseline 触发过 replan 的案例上对比 baseline / no_replan。"""
    noreplan_map = {r.get("caseId"): r for r in noreplan_results}
    case_details = []
    for br in baseline_results:
        analysis = br.get("replanAnalysis") or {}
        if not analysis.get("triggered", False):
            continue
        nr = noreplan_map.get(br.get("caseId"))
        if nr is None:
            continue
        b_csr = _csr(br)
        n_csr = _csr(nr)
        b_side = _side(br, b_csr)
        n_side = _side(nr, n_csr)
        case_details.append({
            "caseId": br.get("caseId"),
            "replanTypes": list(analysis.get("types") or []),
            "replanCount": analysis.get("count", 0),
            "baseline": b_side,
            "noReplan": n_side,
            "deltas": {
                "csr": round(b_csr - n_csr, 4),
                "reflectionScore": round(b_side["reflectionScore"] - n_side["reflectionScore"], 2),
                "candidateCount": b_side["candidateCount"] - n_side["candidateCount"],
                "totalTokens": b_side["totalTokens"] - n_side["totalTokens"],
                "responseTimeMs": round(b_side["responseTimeMs"] - n_side["responseTimeMs"], 1),
            },
            "replanEffective": (b_csr > n_csr) or (b_side["reflectionScore"] > n_side["reflectionScore"]),
        })

    total = len(case_details)
    effective = sum(1 for c in case_details if c["replanEffective"])
    if total:
        avg_csr = sum(c["deltas"]["csr"] for c in case_details) / total
        avg_reflect = sum(c["deltas"]["reflectionScore"] for c in case_details) / total
        avg_candidates = sum(c["deltas"]["candidateCount"] for c in case_details) / total
        avg_tokens = sum(c["deltas"]["totalTokens"] for c in case_details) / total
    else:
        avg_csr = avg_reflect = avg_candidates = avg_tokens = 0
    return {
        "totalReplanCases": total,
        "effectiveCount": effective,
        "replanSuccessRate": round(effective / total, 4) if total else 0,
        "avgDeltaCSR": round(avg_csr, 4),
        "avgDeltaReflectionScore": round(avg_reflect, 2),
        "avgDeltaCandidateCount": round(avg_candidates, 2),
        "avgDeltaTotalTokens": round(avg_tokens, 1),
        "caseDetails": case_details,
    }

